('const TAP = isMouse ? "クリック" : "タップ";', 'const TAP = isMouse ? "click" : "tap";'),
('const TAP1 = isMouse ? "1回クリック" : "1回タップ";', 'const TAP1 = isMouse ? "single-click" : "single-tap";'),
('const TAP2 = isMouse ? "ダブルクリック" : "ダブルタップ";', 'const TAP2 = isMouse ? "double-click" : "double-tap";'),
('const TAP3 = isMouse ? "トリプルクリック" : "トリプルタップ";', 'const TAP3 = isMouse ? "triple-click" : "triple-tap";'),
('const MENU = isMouse ? "右クリック" : "長押し";', 'const MENU = isMouse ? "right-click" : "long-press";\n  const CAP = (s) => s[0].toUpperCase() + s.slice(1);'),
('{ title: "1. 問題を登録する", text: `使い方を、実際に試しながら説明します。まずは初級編（6ステップ）です。\\n\\n最初の画面の「問題を作る・登録する」から、次のどれかで問題を入れます。\\n・自分で作る：数字を手で入力する（写真から読み取ることもできます）\\n・自動で作る：レベルを選ぶと新しい問題ができます\\n・問題ファイルを読み込む\\n\\n手で入力するときは、小さな数字を${TAP}すると問題の数字になります。全部入れたら「問題登録完了」→「回答スタート」です。`',
 '{ title: "1. Enter a puzzle", text: `This guide explains how to use the app while you try things out. First, the Basics (6 steps).\\n\\nFrom “Create or add a puzzle” on the start screen, add a puzzle in one of these ways:\\n• Enter it yourself: type in the digits (you can also read them from a photo)\\n• Generate a puzzle: choose a level and a new puzzle is created\\n• Load a puzzle file\\n\\nWhen entering by hand, ${TAP} a small digit to make it a given. When you’re done, press “Finish entering” → “Start solving.”`'),
('ask: `下のマスの「3」を${TAP}して、問題の数字として入れてみてください。`,', 'ask: `${CAP(TAP)} “3” in the cell below to enter it as a given.`,'),
('ok: "できました！ 問題の数字が入りました。" },', 'ok: "Done! The given has been entered." },'),
('{ part: 1, title: `2. ${MENU}でメニューを開く`, text: `解くときは、小さな数字を${MENU}するとメニューが出ます。\\nメニューから「候補（青）にする」「確定候補にする」「消す」などを選んで解いていきます。\\n\\n次のページから、実際に試してみましょう。` },', '{ part: 1, title: `2. ${CAP(MENU)} to open the menu`, text: `While solving, ${MENU} a small digit to open a menu.\\nChoose “Mark as candidate (blue),” “Confirm,” “Remove,” and so on from the menu as you solve.\\n\\nLet’s try it on the next pages.` },'),
('{ part: 1, title: "3. 候補を選ぶ・確定候補にする", text: `メニューの「候補（青）にする」で青くなります（候補の印）。\\n「確定候補にする」で大きな青い数字になります（確定候補）。もう一度選ぶと戻ります。`,', '{ part: 1, title: "3. Mark candidates and confirm digits", text: `“Mark as candidate (blue)” in the menu turns the digit blue (a candidate mark).\\n“Confirm” turns it into a large blue digit (a confirmed digit). Choose it again to undo.`,'),
('ask: `「5」を${MENU}して候補（青）にしてから、「7」を${MENU}して確定候補にしてください。`,', 'ask: `${CAP(MENU)} “5” to mark it as a candidate (blue), then ${MENU} “7” to confirm it.`,'),
('ok: "できました！ 青い数字が候補、大きな青い数字が確定候補です。" },', 'ok: "Done! Blue digits are candidates; large blue digits are confirmed." },'),
('{ part: 1, title: "4. 候補を消す", text: `メニューの「消す」を選ぶと、その数字が消えます。\\n同じ行・列・ブロックに同じ数字が確定していれば、まとめて消えます。もう一度選ぶと戻ります。`,', '{ part: 1, title: "4. Remove candidates", text: `Choose “Remove” in the menu to remove that digit.\\nIf the same digit is already placed in the same row, column, or box, they’re all removed at once. Choose it again to restore.`,'),
('ask: `左に「5」が確定しています。真ん中のマスの「5」を${MENU}して、「5 を消す」を選んでください。`,', 'ask: `“5” is placed on the left. ${CAP(MENU)} the “5” in the middle cell and choose “Remove 5.”`,'),
('ok: "できました！ この行の「5」がまとめて消えました。" },', 'ok: "Done! The “5”s in this row were removed at once." },', 2),
('{ part: 1, title: "5. 「戻る」で取り消す", text: "まちがえたときは「戻る」ボタンを押すと、1つ前の操作に戻ります。何回でも戻れます。\\n\\n間違って消した候補は、マスを選んで「候補を復活」（またはメニューの「このマスの消した候補を復活」）でも戻せます。",', '{ part: 1, title: "5. Undo mistakes", text: "If you make a mistake, press “Undo” to go back one step. You can undo as many times as you like.\\n\\nCandidates removed by mistake can also be brought back by selecting the cell and pressing “Restore candidates” (or “Restore removed candidates in this cell” in the menu).",'),
('ask: `「4」を${MENU}して「4 を消す」を選んでから、下の「戻る」を押して元に戻してください。`,', 'ask: `${CAP(MENU)} “4” and choose “Remove 4,” then press “Undo” below to bring it back.`,'),
('ok: "できました！ 「戻る」で1つ前に戻りました。" },', 'ok: "Done! “Undo” took you back one step." },'),
('{ part: 1, title: "6. 自動保存と、解き始め", text: "解いている途中の状態は、この端末に自動で保存されます。アプリを閉じても、次に開くと続きから始まります。\\n「一時停止」でタイマーを止められます。\\n\\nこれで解き始められます。速く解く操作や、ヒント・保存などは中級編で説明します（アプリ名の右の「？」ボタンからいつでも見られます）。", fork: true },', '{ part: 1, title: "6. Autosave, and getting started", text: "Your progress is saved automatically on this device. Even if you close the app, it picks up where you left off next time.\\n“Pause” stops the timer.\\n\\nYou’re ready to start solving. Faster controls, hints, saving, and more are covered in the Intermediate guide (you can open it anytime with the “?” button next to the app name).", fork: true },'),
('{ part: 2, title: "ようこそ（中級編）", text: `慣れてきたら、${MENU}でメニューから選ぶより、${TAP}の回数で操作するほうが速くて効率的です。\\n\\n・${TAP1}：候補を選ぶ\\n・${TAP2}：確定候補にする\\n・${TAP3}：候補を消す\\n\\n次のページから、実際に試してみましょう。${MENU}のメニューも、これまでどおり使えます。` },', '{ part: 2, title: "Welcome (Intermediate)", text: `Once you’re used to it, using the number of ${TAP}s is faster than choosing from the ${MENU} menu.\\n\\n• ${CAP(TAP1)}: mark a candidate\\n• ${CAP(TAP2)}: confirm a digit\\n• ${CAP(TAP3)}: remove a candidate\\n\\nLet’s try it on the next pages. The ${MENU} menu still works as before.` },'),
('{ part: 2, title: `${TAP1}：候補を選ぶ`, text: `小さな数字を${TAP1}すると青くなります（候補の印）。もう${TAP1}で戻ります。`,', '{ part: 2, title: `${CAP(TAP1)}: mark a candidate`, text: `${CAP(TAP1)} a small digit to turn it blue (a candidate mark). ${CAP(TAP1)} again to undo.`,'),
('ask: `下のマスの「5」を${TAP1}してみてください。`,', 'ask: `${CAP(TAP1)} the “5” in the cell below.`,'),
('ok: "できました！ 青い数字が候補です。" },', 'ok: "Done! Blue digits are candidates." },'),
('{ part: 2, title: `${TAP2}：確定候補にする`, text: `小さな数字を${TAP2}すると、大きな青い数字になります（確定候補）。もう一度${TAP2}で戻ります。`,', '{ part: 2, title: `${CAP(TAP2)}: confirm a digit`, text: `${CAP(TAP2)} a small digit to turn it into a large blue digit (a confirmed digit). ${CAP(TAP2)} again to undo.`,'),
('ask: `「7」を${TAP2}してみてください。`,', 'ask: `${CAP(TAP2)} “7”.`,'),
('ok: "できました！ 大きな青い数字が確定候補です。" },', 'ok: "Done! Large blue digits are confirmed digits." },'),
('{ part: 2, title: `${TAP3}：候補を消す`, text: `小さな数字を${TAP3}すると、その数字が消えます。\\n同じ行・列・ブロックに同じ数字が確定していれば、まとめて消えます。もう一度${TAP3}で戻ります。`,', '{ part: 2, title: `${CAP(TAP3)}: remove a candidate`, text: `${CAP(TAP3)} a small digit to remove it.\\nIf the same digit is already placed in the same row, column, or box, they’re all removed at once. ${CAP(TAP3)} again to restore.`,'),
('ask: `左に「5」が確定しています。真ん中のマスの「5」を${TAP3}してみてください。`,', 'ask: `“5” is placed on the left. ${CAP(TAP3)} the “5” in the middle cell.`,'),
('{ part: 2, title: `大きな数字を${TAP3}`, text: `大きな数字を${TAP3}すると、同じ行・列・ブロックにある同じ数字の候補がまとめて消えます。`,', '{ part: 2, title: `${CAP(TAP3)} a large digit`, text: `${CAP(TAP3)} a large digit to remove all candidates of that digit in the same row, column, and box at once.`,'),
('ask: `左の大きな「8」を${TAP3}してみてください。`,', 'ask: `${CAP(TAP3)} the large “8” on the left.`,'),
('ok: "できました！ ほかのマスの「8」が消えました。" },', 'ok: "Done! The “8”s in the other cells were removed." },'),
('{ part: 2, title: "問題を作る：写真から読み取る", text: `「写真から問題を読み取る」で、撮影・画像ファイル・貼り付けのどれかを選びます。\\n四隅のオレンジの丸を盤の角に合わせて「読み取る」を押します。\\n読み取った数字は写真と見比べて、まちがいを直してください。自信のない数字には「?」が付きます。\\n\\nコツ：真上から明るい場所で撮る`,', '{ part: 2, title: "Create a puzzle: read from a photo", text: `Under “Read a puzzle from a photo,” choose to take a photo, pick an image file, or paste.\\nMove the four orange circles onto the board’s corners and press “Read.”\\nCompare the digits that were read with the photo and fix any mistakes. Uncertain digits are marked with “?”.\\n\\nTip: shoot from directly above in a bright place`,'),
('{ part: 2, title: "数字をハイライトする", text: `盤の下の1〜9を${TAP}すると、その数字が入る可能性のある候補が点滅し、確定している同じ数字に色が付きます。\\n続けて別の数字を${TAP}すると、別の色で4つまで同時に表示できます。もう一度${TAP}でその数字だけ止まります。\\n盤に9つそろった数字は、押せなくなります。` },', '{ part: 2, title: "Highlight digits", text: `${CAP(TAP)} 1–9 below the board to make that digit’s possible candidates blink and color the same placed digits.\\n${CAP(TAP)} another digit to show it in a different color; up to 4 at once. ${CAP(TAP)} again to turn off just that digit.\\nDigits that are already placed 9 times can’t be pressed.` },'),
('{ part: 2, title: "ヒント", text: "「ヒント」で、解き方を選べます。右の★の数がレベルです。\\n各行の「？」を押すと、その解き方の説明が出ます。\\n「答えと理由」で入る数字と理由が分かり、「ヒントを消す」で表示を消せます。\\n\\n使った回数はタイマーの右に出ます。" },', '{ part: 2, title: "Hints", text: "“Hint” lets you choose a solving technique. The number of ★ on the right is its level.\\nPress the “?” on each row to see an explanation of that technique.\\n“Answer and reason” tells you a digit and why, and “Clear hint” removes the display.\\n\\nThe number of hints used is shown to the right of the timer." },'),
('{ part: 2, title: "ファイルとGoogleドライブに保存", text: "別の日や別の端末で続きを解くときは、端末の外に保存します。\\n・ファイルに保存：「この状態を保存」→「ファイルに保存」（保存先がGoogleドライブを優先のときは「Googleドライブに保存」）。開くときは「問題を解く」→「回答中のファイルを開く」\\n・Googleドライブ：🏠→「設定」で「Googleドライブに接続」し、保存先を選びます（Googleドライブを優先／保存のたびに選ぶ／この端末）。Googleドライブには「Sudoku」フォルダに保存されます。PCとスマホで同じ問題の続きを解けます\\n・開くときは「問題を解く」→「Googleドライブから開く」（接続しているときだけ出ます）。問題ごとに、問題・回答の途中・完成形が並びます\\n\\nGoogleドライブはアプリ版・Web版で使えます。" },', '{ part: 2, title: "Save to a file or Google Drive", text: "To continue on another day or another device, save outside this device.\\n• Save to a file: “Save this state” → “Save to a file” (“Save to Google Drive” when Google Drive is preferred). To open it: “Solve a puzzle” → “Open an in-progress file”\\n• Google Drive: go to 🏠 → “Settings,” press “Connect to Google Drive,” and choose where to save (Prefer Google Drive / Ask every time / This device). Files go in the “Sudoku” folder in Google Drive, so you can continue the same puzzle on your PC and phone\\n• To open: “Solve a puzzle” → “Open from Google Drive” (shown only when connected). For each puzzle you’ll see the puzzle, in-progress saves, and the solved grid\\n\\nGoogle Drive works in the installed app and web versions." },'),
('{ part: 2, title: "完成したら", text: "全マスが大きな数字で埋まり、赤がなければ完成です。\\n・検証：途中でも、確定したマスを正解と比べ、違うマスを赤い背景で示します\\n・再生：確定した順に数字を再生します（解いている途中でも使えます）\\n・完成形を保存：完成した盤をファイルやGoogleドライブに残します\\n・一覧の「完成を見る」：あとから完成した盤を開けます" },', '{ part: 2, title: "When you’re done", text: "The puzzle is solved when every cell has a large digit and nothing is red.\\n• Check: even mid-way, compares confirmed cells with the solution and shows wrong ones with a red background\\n• Replay: replays the digits in the order you confirmed them (works while solving, too)\\n• Save solved grid: keeps the solved board in a file or Google Drive\\n• “View solution” in the list: opens the solved board later" },'),
('{ part: 2, title: "色の意味", text: "数字の色の意味です。", colors: [', '{ part: 2, title: "What the colors mean", text: "Here’s what the digit colors mean.", colors: ['),
('["blue", "5", "青", "選んだ候補"],', '["blue", "5", "Blue", "Marked candidate"],'),
('["red", "3", "赤", "数字の重複"],', '["red", "3", "Red", "Duplicate digit"],'),
('["brown", "6", "茶", "入らない候補"],', '["brown", "6", "Brown", "Candidate that can’t fit"],'),
('{ part: 2, title: "ボタン", text: "【よく使う操作】\\n戻る：1つ前の操作に戻す（パソコンは Ctrl+Z でも可）\\nヒント：次に使える解き方を示す\\n検証：確定したマスを正解と比べる\\n表示方法変更：未確定のマスを空白／候補を表示／正解を表示\\n\\n【状態の管理】\\nこの状態を保存：その時点を残す\\n保存した状態に戻す：残した時点に戻る\\n再生：確定した順に数字を再生する\\n\\n【問題の管理】\\nリセット：問題だけの最初の状態に戻す\\n問題一覧へ：問題の一覧に戻る\\n\\n一時停止：タイマーを止める。一時停止中は保存と問題の管理だけ使えます\\n\\n" + (matchMedia("(hover: hover) and (pointer: fine)").matches ? "ボタンにマウスを乗せると" : "ボタンを長押しすると") + "、説明が出ます" },', '{ part: 2, title: "Buttons", text: "[Common actions]\\nUndo: go back one step (Ctrl+Z also works on a computer)\\nHint: shows the next technique you can use\\nCheck: compares confirmed cells with the solution\\nView: hide candidates in open cells / show candidates / show solution\\n\\n[Saved states]\\nSave this state: keeps the current point\\nRestore a saved state: returns to a kept point\\nReplay: replays digits in the order you confirmed them\\n\\n[Puzzle]\\nReset: back to the puzzle’s starting state\\nPuzzle list: back to the list of puzzles\\n\\nPause: stops the timer. While paused, only saving and the puzzle actions are available\\n\\n" + (matchMedia("(hover: hover) and (pointer: fine)").matches ? "Hover over a button" : "Long-press a button") + " to see what it does" },'),
('{ part: 2, title: "準備ができました", text: "このガイドは、アプリ名の右の「？」ボタンからいつでも見られます。", last: true },', '{ part: 2, title: "You’re all set", text: "You can open this guide anytime with the “?” button next to the app name.", last: true },'),
